CREATE TABLE IF NOT EXISTS leaderboard_stats (id TEXT PRIMARY KEY,user_id TEXT,username TEXT NOT NULL DEFAULT 'Trainer',biggest_pull NUMERIC(18,2) NOT NULL DEFAULT 0,packs_opened INTEGER NOT NULL DEFAULT 0,upgrades_attempted INTEGER NOT NULL DEFAULT 0,is_deleted INTEGER NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_leaderboard_pulls ON leaderboard_stats(biggest_pull DESC); CREATE INDEX IF NOT EXISTS idx_leaderboard_packs ON leaderboard_stats(packs_opened DESC); CREATE INDEX IF NOT EXISTS idx_leaderboard_upgrades ON leaderboard_stats(upgrades_attempted DESC);
